//! R8 fail-closed eligibility semantics gate. Review-only; no trading.
use serde_json::json;
#[derive(Clone,Copy)]struct M{spot:bool,fut:bool,spot_live:bool,fut_live:bool,spot_step:Option<f64>,fut_step:Option<f64>,spot_min:Option<f64>,fut_min:Option<f64>,contract:Option<f64>,loaded_ns:u64}
fn static_reason(m:M)->Option<&'static str>{if !m.spot||!m.fut{Some("EXCHANGE_MINIMUM_UNKNOWN")}else if !m.spot_live||!m.fut_live{Some("MARKET_INACTIVE")}else if m.spot_step.is_none()||m.fut_step.is_none()||m.spot_min.is_none()||m.fut_min.is_none()||m.contract.is_none(){Some("EXCHANGE_MINIMUM_UNKNOWN")}else if m.contract!=Some(1.0){Some("UNSUPPORTED_CONTRACT_SIZE")}else{None}}
fn state(m:M,now:u64,ttl:u64)->&'static str{match static_reason(m){Some("MARKET_INACTIVE")=>"INSTRUMENT_INACTIVE",Some("EXCHANGE_MINIMUM_UNKNOWN")=>"SIZE_METADATA_MISSING",Some(_)=>"SIZE_METADATA_INVALID",None if m.loaded_ns==0=>"SIZE_METADATA_INVALID",None if now-m.loaded_ns>ttl*1_000_000=>"SIZE_METADATA_STALE",None=>"SIZE_METADATA_READY"}}
fn main(){let good=M{spot:true,fut:true,spot_live:true,fut_live:true,spot_step:Some(0.001),fut_step:Some(0.001),spot_min:Some(0.001),fut_min:Some(0.001),contract:Some(1.),loaded_ns:1_000_000_000};let cases=[("ready",good,1_100_000_000,"SIZE_METADATA_READY"),("missing_spot",M{spot:false,..good},1_100_000_000,"SIZE_METADATA_MISSING"),("missing_step",M{spot_step:None,..good},1_100_000_000,"SIZE_METADATA_MISSING"),("inactive_spot",M{spot_live:false,..good},1_100_000_000,"INSTRUMENT_INACTIVE"),("inactive_future",M{fut_live:false,..good},1_100_000_000,"INSTRUMENT_INACTIVE"),("bad_contract",M{contract:Some(10.),..good},1_100_000_000,"SIZE_METADATA_INVALID"),("zero_loaded",M{loaded_ns:0,..good},1_100_000_000,"SIZE_METADATA_INVALID"),("stale",good,7_000_000_000,"SIZE_METADATA_STALE")];let mut bad=Vec::new();for(n,m,now,want)in cases{let got=state(m,now,1000);if got!=want{bad.push(json!({"case":n,"got":got,"want":want}));}}println!("{}",json!({"r8_fail_closed":bad.is_empty(),"cases":8,"failures":bad,"trading":false}));}